// block-per-quartet: 32 threads, smem = (RSZ+NTC+2*35*25)*sizeof(TR)
template<typename TR>
__global__ void routec_block_l2(int nq, int kprim,
    const TR* __restrict__ dRs, const TR* __restrict__ dTc,
    const TR* __restrict__ FTpool, const int2* __restrict__ qlist,
    TR* __restrict__ out){
  const int q = blockIdx.x;  if(q >= nq) return;
  const int tid = threadIdx.x;
  extern __shared__ unsigned char smem_raw[];
  TR* smem = (TR*)smem_raw;
  TR* sRs = smem;            // [164]
  TR* sTc = smem + 164;    // [195]
  TR* sGb = smem + 359;            // [35*25]
  TR* sGk = smem + 1234;  // [35*25]
  TR O[25];
  #pragma unroll
  for(int jc=0;jc<25;++jc) O[jc] = TR(0.0);
  for(int pq=0; pq<kprim; ++pq){
    const long base = (long)q*kprim + pq;
    __syncthreads();  // prior iteration's smem reads complete
    for(int s=tid; s<164; s+=32) sRs[s] = dRs[base*164+s];
    for(int s=tid; s<195; s+=32) sTc[s] = dTc[base*195+s];
    const int ib = qlist[base].x, ik = qlist[base].y;
    const TR* __restrict__ FTb = FTpool + (size_t)ib*875;
    const TR* __restrict__ FTk = FTpool + (size_t)ik*875;
    __syncthreads();
    if(tid < 25){
      sGb[325+tid] = FTb[0+tid];
