    const TR* __restrict__ FTpool, const int2* __restrict__ qlist,
    TR* __restrict__ out){
  const int q = blockIdx.x;  if(q >= nq) return;
  const int tid = threadIdx.x;
  extern __shared__ unsigned char smem_raw[];
  TR* smem = (TR*)smem_raw;
  TR* sRs = smem;            // [164]
  TR* sTc = smem + 164;    // [126]
