  const TR s1_0_2_0 = TR(1.0)*s2_0_0_0;
  const TR s2_0_2_0 = TR(1.0)*s3_0_0_0;
  const TR s0_0_0_2 = Rn*s1_0_0_1 + TR(1.0)*s1_0_0_0;
  const TR s1_0_0_2 = Rn*s2_0_0_1 + TR(1.0)*s2_0_0_0;
  const TR s2_0_0_2 = Rn*s3_0_0_1 + TR(1.0)*s3_0_0_0;
  const TR s0_2_0_1 = TR(1.0)*s1_0_0_1;
  const TR s1_2_0_1 = TR(1.0)*s2_0_0_1;
  const TR s0_0_2_1 = TR(1.0)*s1_0_0_1;
  const TR s1_0_2_1 = TR(1.0)*s2_0_0_1;
  const TR s0_0_0_3 = Rn*s1_0_0_2 + TR(2.0)*s1_0_0_1;
  const TR s1_0_0_3 = Rn*s2_0_0_2 + TR(2.0)*s2_0_0_1;
  const TR s0_4_0_0 = TR(3.0)*s1_2_0_0;
  const TR s0_2_2_0 = TR(1.0)*s1_0_2_0;
  const TR s0_2_0_2 = TR(1.0)*s1_0_0_2;
  const TR s0_0_4_0 = TR(3.0)*s1_0_2_0;
  const TR s0_0_2_2 = TR(1.0)*s1_0_0_2;
  const TR s0_0_0_4 = Rn*s1_0_0_3 + TR(3.0)*s1_0_0_2;
  const TR h0_0 = TR(0.9999999999999997)*s0_0_0_0;
  const TR h1_0 = TR(1.0000000000000004)*s0_0_0_1;
  const TR h2_0 = TR(0.9999999999999997)*s0_2_0_0 + TR(0.9999999999999997)*s0_0_2_0 + TR(0.9999999999999997)*s0_0_0_2;
  const TR h2_1 = TR(-0.500000000000001)*s0_2_0_0 + TR(-0.4999999999999994)*s0_0_2_0 + TR(0.9999999999999999)*s0_0_0_2;
  const TR h3_0 = TR(1.0000000000000004)*s0_2_0_1 + TR(1.0000000000000004)*s0_0_2_1 + TR(1.0000000000000004)*s0_0_0_3;
  const TR h3_1 = TR(-1.4999999999999996)*s0_2_0_1 + TR(-1.5000000000000018)*s0_0_2_1 + TR(1.0000000000000013)*s0_0_0_3;
  const TR h4_0 = TR(0.9999999999999997)*s0_4_0_0 + TR(1.9999999999999993)*s0_2_2_0 + TR(1.9999999999999993)*s0_2_0_2 + TR(0.9999999999999997)*s0_0_4_0 + TR(1.9999999999999993)*s0_0_2_2 + TR(0.9999999999999997)*s0_0_0_4;
  const TR h4_1 = TR(-0.500000000000001)*s0_4_0_0 + TR(-1.0000000000000004)*s0_2_2_0 + TR(0.4999999999999989)*s0_2_0_2 + TR(-0.4999999999999994)*s0_0_4_0 + TR(0.5000000000000004)*s0_0_2_2 + TR(0.9999999999999999)*s0_0_0_4;
  const TR h4_2 = TR(0.3750000000000014)*s0_4_0_0 + TR(0.7500000000000012)*s0_2_2_0 + TR(-3.0000000000000027)*s0_2_0_2 + TR(0.37500000000000017)*s0_0_4_0 + TR(-3.0)*s0_0_2_2 + TR(1.0)*s0_0_0_4;
  TR* __restrict__ Tq = dTc + q*48;
  Tq[0] = pref*(TR(0.20000000000000037)*h4_0 + TR(-0.2857142857142859)*h4_1 + TR(0.08571428571428596)*h4_2);
  Tq[1] = pref*(TR(-0.3333333333333339)*h2_0 + TR(0.3333333333333338)*h2_1);
  Tq[2] = pref*(TR(-0.34641016151377585)*h3_0 + TR(0.34641016151377546)*h3_1);
  Tq[3] = pref*(TR(-0.3333333333333339)*h4_0 + TR(0.33333333333333376)*h4_1);
  Tq[4] = pref*(TR(-0.3499271061118827)*h4_1 + TR(0.3499271061118827)*h4_2);
  Tq[5] = pref*(TR(0.34641016151377585)*h3_0 + TR(-0.34641016151377546)*h3_1);
  Tq[6] = pref*(TR(0.20000000000000046)*h4_0 + TR(0.14285714285714285)*h4_1 + TR(-0.34285714285714286)*h4_2);
  Tq[7] = pref*(TR(-0.3333333333333339)*h4_0 + TR(0.33333333333333376)*h4_1);
  Tq[8] = pref*(TR(-0.3499271061118827)*h4_1 + TR(0.3499271061118827)*h4_2);
  Tq[9] = pref*(TR(0.9999999999999998)*h0_0);
  Tq[10] = pref*(TR(0.9999999999999996)*h1_0);
  Tq[11] = pref*(TR(0.9999999999999998)*h2_0);
  Tq[12] = pref*(TR(0.9999999999999996)*h2_1);
  Tq[13] = pref*(TR(0.9999999999999997)*h3_0);
  Tq[14] = pref*(TR(0.9999999999999996)*h3_1);
  Tq[15] = pref*(TR(0.9999999999999998)*h4_0);
  Tq[16] = pref*(TR(0.9999999999999998)*h4_1);
  Tq[17] = pref*(TR(0.9999999999999997)*h4_2);
  Tq[18] = pref*(TR(-0.9999999999999996)*h1_0);
  Tq[19] = pref*(TR(-0.33333333333333387)*h2_0 + TR(-0.6666666666666672)*h2_1);
  Tq[20] = pref*(TR(-0.9999999999999997)*h3_0);
  Tq[21] = pref*(TR(-0.3999999999999994)*h3_0 + TR(-0.5999999999999998)*h3_1);
  Tq[22] = pref*(TR(-0.3333333333333339)*h4_0 + TR(-0.6666666666666674)*h4_1);
  Tq[23] = pref*(TR(-0.4285714285714297)*h4_1 + TR(-0.571428571428572)*h4_2);
  Tq[24] = pref*(TR(0.9999999999999998)*h2_0);
  Tq[25] = pref*(TR(0.9999999999999997)*h3_0);
  Tq[26] = pref*(TR(0.9999999999999998)*h4_0);
  Tq[27] = pref*(TR(0.9999999999999998)*h4_1);
  Tq[28] = pref*(TR(0.9999999999999996)*h2_1);
  Tq[29] = pref*(TR(0.3999999999999994)*h3_0 + TR(0.5999999999999998)*h3_1);
  Tq[30] = pref*(TR(0.9999999999999998)*h4_1);
  Tq[31] = pref*(TR(0.2)*h4_0 + TR(0.28571428571428575)*h4_1 + TR(0.5142857142857141)*h4_2);
  Tq[32] = pref*(TR(-0.9999999999999997)*h3_0);
  Tq[33] = pref*(TR(-0.3333333333333339)*h4_0 + TR(-0.6666666666666674)*h4_1);
  Tq[34] = pref*(TR(-0.9999999999999996)*h3_1);
  Tq[35] = pref*(TR(-0.4285714285714297)*h4_1 + TR(-0.571428571428572)*h4_2);
  Tq[36] = pref*(TR(0.9999999999999998)*h4_0);
  Tq[37] = pref*(TR(0.9999999999999998)*h4_1);
  Tq[38] = pref*(TR(0.9999999999999997)*h4_2);
  Tq[39] = pref*(TR(-0.3333333333333334)*h2_0 + TR(0.3333333333333333)*h2_1);
  Tq[40] = pref*(TR(-0.34641016151377585)*h3_0 + TR(0.34641016151377546)*h3_1);
  Tq[41] = pref*(TR(-0.33333333333333337)*h4_0 + TR(0.3333333333333333)*h4_1);
  Tq[42] = pref*(TR(-0.34992710611188177)*h4_1 + TR(0.3499271061118821)*h4_2);
  Tq[43] = pref*(TR(0.34641016151377585)*h3_0 + TR(-0.34641016151377546)*h3_1);
  Tq[44] = pref*(TR(0.2000000000000004)*h4_0 + TR(0.1428571428571429)*h4_1 + TR(-0.3428571428571432)*h4_2);
  Tq[45] = pref*(TR(-0.33333333333333337)*h4_0 + TR(0.3333333333333333)*h4_1);
  Tq[46] = pref*(TR(-0.34992710611188177)*h4_1 + TR(0.3499271061118821)*h4_2);
  Tq[47] = pref*(TR(0.20000000000000023)*h4_0 + TR(-0.28571428571428625)*h4_1 + TR(0.08571428571428563)*h4_2);
}
// block-per-quartet: 32 threads, smem = (RSZ+NTC+2*35*25)*sizeof(TR)
template<typename TR>
__global__ void routec_block_l2_c4(int nq, int kprim,
    const TR* __restrict__ dRs, const TR* __restrict__ dTc,
    const TR* __restrict__ FTpool, const int2* __restrict__ qlist,
    TR* __restrict__ out){
  const int q = blockIdx.x;  if(q >= nq) return;
  const int tid = threadIdx.x;
  extern __shared__ unsigned char smem_raw[];
  TR* smem = (TR*)smem_raw;
  TR* sRs = smem;            // [164]
  TR* sTc = smem + 164;    // [48]
  TR* sGb = smem + 212;            // [35*25]
  TR* sGk = smem + 1087;  // [35*25]
  TR O[25];
  #pragma unroll
  for(int jc=0;jc<25;++jc) O[jc] = TR(0.0);
  for(int pq=0; pq<kprim; ++pq){
    const long base = (long)q*kprim + pq;
    __syncthreads();  // prior iteration's smem reads complete
    for(int s=tid; s<164; s+=32) sRs[s] = dRs[base*164+s];
    for(int s=tid; s<48; s+=32) sTc[s] = dTc[base*48+s];
    const int ib = qlist[base].x, ik = qlist[base].y;
    const TR* __restrict__ FTb = FTpool + (size_t)ib*875;
    const TR* __restrict__ FTk = FTpool + (size_t)ik*875;
    __syncthreads();
    if(tid < 25){
      sGb[325+tid] = FTb[0+tid];
      { // k=1 lam=1
        const TR f0=FTb[25+tid];
        const TR f1=FTb[50+tid];
        const TR f2=FTb[75+tid];
        sGb[175+tid] = sRs[0]*f0 + sRs[3]*f1 + sRs[6]*f2;
        sGb[350+tid] = sRs[1]*f0 + sRs[4]*f1 + sRs[7]*f2;
        sGb[550+tid] = sRs[2]*f0 + sRs[5]*f1 + sRs[8]*f2;
      }
      sGb[375+tid] = FTb[100+tid];
      { // k=2 lam=2
        const TR f0=FTb[125+tid];
        const TR f1=FTb[150+tid];
        const TR f2=FTb[175+tid];
        const TR f3=FTb[200+tid];
        const TR f4=FTb[225+tid];
        sGb[75+tid] = sRs[9]*f0 + sRs[14]*f1 + sRs[19]*f2 + sRs[24]*f3 + sRs[29]*f4;
        sGb[200+tid] = sRs[10]*f0 + sRs[15]*f1 + sRs[20]*f2 + sRs[25]*f3 + sRs[30]*f4;
        sGb[400+tid] = sRs[11]*f0 + sRs[16]*f1 + sRs[21]*f2 + sRs[26]*f3 + sRs[31]*f4;
        sGb[575+tid] = sRs[12]*f0 + sRs[17]*f1 + sRs[22]*f2 + sRs[27]*f3 + sRs[32]*f4;
        sGb[700+tid] = sRs[13]*f0 + sRs[18]*f1 + sRs[23]*f2 + sRs[28]*f3 + sRs[33]*f4;
      }
      { // k=3 lam=1
        const TR f0=FTb[250+tid];
        const TR f1=FTb[275+tid];
        const TR f2=FTb[300+tid];
        sGb[225+tid] = sRs[0]*f0 + sRs[3]*f1 + sRs[6]*f2;
        sGb[425+tid] = sRs[1]*f0 + sRs[4]*f1 + sRs[7]*f2;
        sGb[600+tid] = sRs[2]*f0 + sRs[5]*f1 + sRs[8]*f2;
      }
      { // k=3 lam=3
        const TR f0=FTb[325+tid];
        const TR f1=FTb[350+tid];
        const TR f2=FTb[375+tid];
        const TR f3=FTb[400+tid];
        const TR f4=FTb[425+tid];
        const TR f5=FTb[450+tid];
        const TR f6=FTb[475+tid];
        sGb[250+tid] = sRs[36]*f0 + sRs[43]*f1 + sRs[50]*f2 + sRs[57]*f3 + sRs[64]*f4 + sRs[71]*f5 + sRs[78]*f6;
        sGb[450+tid] = sRs[37]*f0 + sRs[44]*f1 + sRs[51]*f2 + sRs[58]*f3 + sRs[65]*f4 + sRs[72]*f5 + sRs[79]*f6;
        sGb[625+tid] = sRs[38]*f0 + sRs[45]*f1 + sRs[52]*f2 + sRs[59]*f3 + sRs[66]*f4 + sRs[73]*f5 + sRs[80]*f6;
      }
      sGb[475+tid] = FTb[500+tid];
      { // k=4 lam=2
        const TR f0=FTb[525+tid];
        const TR f1=FTb[550+tid];
        const TR f2=FTb[575+tid];
        const TR f3=FTb[600+tid];
        const TR f4=FTb[625+tid];
        sGb[500+tid] = sRs[11]*f0 + sRs[16]*f1 + sRs[21]*f2 + sRs[26]*f3 + sRs[31]*f4;
      }
      { // k=4 lam=4
        const TR f0=FTb[650+tid];
        const TR f1=FTb[675+tid];
        const TR f2=FTb[700+tid];
        const TR f3=FTb[725+tid];
        const TR f4=FTb[750+tid];
        const TR f5=FTb[775+tid];
        const TR f6=FTb[800+tid];
        const TR f7=FTb[825+tid];
        const TR f8=FTb[850+tid];
        sGb[525+tid] = sRs[87]*f0 + sRs[96]*f1 + sRs[105]*f2 + sRs[114]*f3 + sRs[123]*f4 + sRs[132]*f5 + sRs[141]*f6 + sRs[150]*f7 + sRs[159]*f8;
      }
      sGk[325+tid] = FTk[0+tid];
      { // k=1 lam=1
        const TR f0=FTk[25+tid];
        const TR f1=FTk[50+tid];
        const TR f2=FTk[75+tid];
        sGk[175+tid] = sRs[0]*f0 + sRs[3]*f1 + sRs[6]*f2;
        sGk[350+tid] = sRs[1]*f0 + sRs[4]*f1 + sRs[7]*f2;
        sGk[550+tid] = sRs[2]*f0 + sRs[5]*f1 + sRs[8]*f2;
      }
      sGk[375+tid] = FTk[100+tid];
      { // k=2 lam=2
        const TR f0=FTk[125+tid];
        const TR f1=FTk[150+tid];
        const TR f2=FTk[175+tid];
        const TR f3=FTk[200+tid];
        const TR f4=FTk[225+tid];
        sGk[75+tid] = sRs[9]*f0 + sRs[14]*f1 + sRs[19]*f2 + sRs[24]*f3 + sRs[29]*f4;
        sGk[200+tid] = sRs[10]*f0 + sRs[15]*f1 + sRs[20]*f2 + sRs[25]*f3 + sRs[30]*f4;
        sGk[400+tid] = sRs[11]*f0 + sRs[16]*f1 + sRs[21]*f2 + sRs[26]*f3 + sRs[31]*f4;
        sGk[575+tid] = sRs[12]*f0 + sRs[17]*f1 + sRs[22]*f2 + sRs[27]*f3 + sRs[32]*f4;
        sGk[700+tid] = sRs[13]*f0 + sRs[18]*f1 + sRs[23]*f2 + sRs[28]*f3 + sRs[33]*f4;
      }
      { // k=3 lam=1
        const TR f0=FTk[250+tid];
        const TR f1=FTk[275+tid];
        const TR f2=FTk[300+tid];
        sGk[225+tid] = sRs[0]*f0 + sRs[3]*f1 + sRs[6]*f2;
        sGk[425+tid] = sRs[1]*f0 + sRs[4]*f1 + sRs[7]*f2;
        sGk[600+tid] = sRs[2]*f0 + sRs[5]*f1 + sRs[8]*f2;
      }
      { // k=3 lam=3
        const TR f0=FTk[325+tid];
        const TR f1=FTk[350+tid];
        const TR f2=FTk[375+tid];
        const TR f3=FTk[400+tid];
        const TR f4=FTk[425+tid];
        const TR f5=FTk[450+tid];
        const TR f6=FTk[475+tid];
        sGk[250+tid] = sRs[36]*f0 + sRs[43]*f1 + sRs[50]*f2 + sRs[57]*f3 + sRs[64]*f4 + sRs[71]*f5 + sRs[78]*f6;
        sGk[450+tid] = sRs[37]*f0 + sRs[44]*f1 + sRs[51]*f2 + sRs[58]*f3 + sRs[65]*f4 + sRs[72]*f5 + sRs[79]*f6;
        sGk[625+tid] = sRs[38]*f0 + sRs[45]*f1 + sRs[52]*f2 + sRs[59]*f3 + sRs[66]*f4 + sRs[73]*f5 + sRs[80]*f6;
      }
      sGk[475+tid] = FTk[500+tid];
      { // k=4 lam=2
        const TR f0=FTk[525+tid];
        const TR f1=FTk[550+tid];
        const TR f2=FTk[575+tid];
        const TR f3=FTk[600+tid];
        const TR f4=FTk[625+tid];
        sGk[500+tid] = sRs[11]*f0 + sRs[16]*f1 + sRs[21]*f2 + sRs[26]*f3 + sRs[31]*f4;
      }
      { // k=4 lam=4
        const TR f0=FTk[650+tid];
        const TR f1=FTk[675+tid];
        const TR f2=FTk[700+tid];
        const TR f3=FTk[725+tid];
        const TR f4=FTk[750+tid];
        const TR f5=FTk[775+tid];
        const TR f6=FTk[800+tid];
        const TR f7=FTk[825+tid];
        const TR f8=FTk[850+tid];
        sGk[525+tid] = sRs[87]*f0 + sRs[96]*f1 + sRs[105]*f2 + sRs[114]*f3 + sRs[123]*f4 + sRs[132]*f5 + sRs[141]*f6 + sRs[150]*f7 + sRs[159]*f8;
      }
    }
    __syncthreads();
    if(tid < 25){
      { const TR w = sTc[0]*sGb[75+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[75+jc]; }
      { const TR w = sTc[1]*sGb[175+tid] + sTc[2]*sGb[200+tid] + sTc[3]*sGb[225+tid] + sTc[4]*sGb[250+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[175+jc]; }
      { const TR w = sTc[5]*sGb[175+tid] + sTc[6]*sGb[200+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[200+jc]; }
      { const TR w = sTc[7]*sGb[175+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[225+jc]; }
      { const TR w = sTc[8]*sGb[175+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[250+jc]; }
      { const TR w = sTc[9]*sGb[325+tid] + sTc[10]*sGb[350+tid] + sTc[11]*sGb[375+tid] + sTc[12]*sGb[400+tid] + sTc[13]*sGb[425+tid] + sTc[14]*sGb[450+tid] + sTc[15]*sGb[475+tid] + sTc[16]*sGb[500+tid] + sTc[17]*sGb[525+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[325+jc]; }
      { const TR w = sTc[18]*sGb[325+tid] + sTc[19]*sGb[350+tid] + sTc[20]*sGb[375+tid] + sTc[21]*sGb[400+tid] + sTc[22]*sGb[425+tid] + sTc[23]*sGb[450+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[350+jc]; }
      { const TR w = sTc[24]*sGb[325+tid] + sTc[25]*sGb[350+tid] + sTc[26]*sGb[375+tid] + sTc[27]*sGb[400+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[375+jc]; }
      { const TR w = sTc[28]*sGb[325+tid] + sTc[29]*sGb[350+tid] + sTc[30]*sGb[375+tid] + sTc[31]*sGb[400+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[400+jc]; }
      { const TR w = sTc[32]*sGb[325+tid] + sTc[33]*sGb[350+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[425+jc]; }
      { const TR w = sTc[34]*sGb[325+tid] + sTc[35]*sGb[350+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[450+jc]; }
      { const TR w = sTc[36]*sGb[325+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[475+jc]; }
      { const TR w = sTc[37]*sGb[325+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[500+jc]; }
      { const TR w = sTc[38]*sGb[325+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[525+jc]; }
      { const TR w = sTc[39]*sGb[550+tid] + sTc[40]*sGb[575+tid] + sTc[41]*sGb[600+tid] + sTc[42]*sGb[625+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[550+jc]; }
      { const TR w = sTc[43]*sGb[550+tid] + sTc[44]*sGb[575+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[575+jc]; }
      { const TR w = sTc[45]*sGb[550+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[600+jc]; }
      { const TR w = sTc[46]*sGb[550+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[625+jc]; }
      { const TR w = sTc[47]*sGb[700+tid];
        #pragma unroll
        for(int jc=0;jc<25;++jc) O[jc] += w*sGk[700+jc]; }
    }
  } // kprim loop
  if(tid < 25){
    TR* __restrict__ o = out + (size_t)q*625 + (size_t)tid*25;
    #pragma unroll
