constexpr size_t SMEMN_BLOCK_l3_c10 = (size_t)(454+636+2*84*49);  // elements
// ---- l=3 truncated at L_cut=8 (multipole band)
constexpr int NTC_l3_c8 = 371;
template<typename TR>
__global__ void routec_scalar_l3_c8(long nprimq, const int2* __restrict__ qlist,
    const double* __restrict__ pairPC, TR* __restrict__ dRs, TR* __restrict__ dTc){
  const long q = (long)blockIdx.x*blockDim.x + threadIdx.x;
  if(q >= nprimq) return;
  const int ib = qlist[q].x, ik = qlist[q].y;
  const double Px=pairPC[ib*4],Py=pairPC[ib*4+1],Pz=pairPC[ib*4+2],p=pairPC[ib*4+3];
  const double Qx=pairPC[ik*4],Qy=pairPC[ik*4+1],Qz=pairPC[ik*4+2],qq=pairPC[ik*4+3];
  const double Rx=Px-Qx, Ry=Py-Qy, Rz=Pz-Qz;
  const double RnD=sqrt(Rx*Rx+Ry*Ry+Rz*Rz);
  const TR Rn=(TR)RnD;
  const TR eta=(TR)(p*qq/(p+qq));
  const TR pref=(TR)(34.986836655249725/(p*qq*sqrt(p+qq)));
  // R->0: any orthonormal frame is exact (V continuous, frame-dependence O(Rn))
