    const double* __restrict__ pcB, const double* __restrict__ pcK,
    TR* __restrict__ dRs, TR* __restrict__ dTc){
  const long q = (long)blockIdx.x*blockDim.x + threadIdx.x;
  if(q >= nprimq) return;
  const int ib = qlist[q].x, ik = qlist[q].y;
  const double Px=pcB[ib*4],Py=pcB[ib*4+1],Pz=pcB[ib*4+2],p=pcB[ib*4+3];
  const double Qx=pcK[ik*4],Qy=pcK[ik*4+1],Qz=pcK[ik*4+2],qq=pcK[ik*4+3];
  const double Rx=Px-Qx, Ry=Py-Qy, Rz=Pz-Qz;
  const double RnD=sqrt(Rx*Rx+Ry*Ry+Rz*Rz);
  const TR Rn=(TR)RnD;
  const TR eta=(TR)(p*qq/(p+qq));
  const TR pref=(TR)(34.986836655249725/(p*qq*sqrt(p+qq)));
  TR Fb_[1]; gen_boys_dev<TR>(0, eta*Rn*Rn, Fb_);
  const TR m2 = TR(-2.0)*eta;
  const TR s0_0_0_0 = Fb_[0];
  const TR h0_0 = TR(0.9999999999999997)*s0_0_0_0;
  TR* __restrict__ Tq = dTc + q*1;
  Tq[0] = pref*(TR(0.9999999999999998)*h0_0);
}
template<typename TR>
__global__ void routec_block_0000(int nq, int kprim,
    const TR* __restrict__ dRs, const TR* __restrict__ dTc,
    const TR* __restrict__ ftB, const TR* __restrict__ ftK,
    const int2* __restrict__ qlist, TR* __restrict__ out){
  const int q = blockIdx.x;  if(q >= nq) return;
  const int tid = threadIdx.x;
  extern __shared__ unsigned char smem_raw[];
  TR* smem = (TR*)smem_raw;
  TR* sRs = smem;            // [0]
  TR* sTc = smem + 0;    // [1]
  TR* sGb = smem + 1;            // [1*1]
  TR* sGk = smem + 2;  // [1*1]
  TR O[1];
  #pragma unroll
  for(int jc=0;jc<1;++jc) O[jc] = TR(0.0);
  for(int pq=0; pq<kprim; ++pq){
    const long base = (long)q*kprim + pq;
    __syncthreads();
    for(int s=tid; s<1; s+=32) sTc[s] = dTc[base*1+s];
    const int ib = qlist[base].x, ik = qlist[base].y;
    const TR* __restrict__ FTb = ftB + (size_t)ib*1;
    const TR* __restrict__ FTk = ftK + (size_t)ik*1;
    __syncthreads();
    if(tid < 1){
      sGb[0+tid] = FTb[0+tid];
    }
    if(tid < 1){
      sGk[0+tid] = FTk[0+tid];
    }
    __syncthreads();
    if(tid < 1){
      { const TR w = sTc[0]*sGb[0+tid];
        #pragma unroll
        for(int jc=0;jc<1;++jc) O[jc] += w*sGk[0+jc]; }
    }
  } // kprim loop
  if(tid < 1){
    TR* __restrict__ o = out + (size_t)q*1 + (size_t)tid*1;
    #pragma unroll
    for(int jc=0;jc<1;++jc) o[jc] = O[jc];
  }
}
constexpr int NTC_K0_1 = 2;
constexpr int RSZ_K0_1 = 9;
template<typename TR>
__global__ void routec_scalar_K0_1(long nprimq, const int2* __restrict__ qlist,
    const double* __restrict__ pcB, const double* __restrict__ pcK,
    TR* __restrict__ dRs, TR* __restrict__ dTc){
  const long q = (long)blockIdx.x*blockDim.x + threadIdx.x;
  if(q >= nprimq) return;
  const int ib = qlist[q].x, ik = qlist[q].y;
  const double Px=pcB[ib*4],Py=pcB[ib*4+1],Pz=pcB[ib*4+2],p=pcB[ib*4+3];
  const double Qx=pcK[ik*4],Qy=pcK[ik*4+1],Qz=pcK[ik*4+2],qq=pcK[ik*4+3];
  const double Rx=Px-Qx, Ry=Py-Qy, Rz=Pz-Qz;
  const double RnD=sqrt(Rx*Rx+Ry*Ry+Rz*Rz);
  const TR Rn=(TR)RnD;
  const TR eta=(TR)(p*qq/(p+qq));
  const TR pref=(TR)(34.986836655249725/(p*qq*sqrt(p+qq)));
  double zx,zy,zz;
  if(RnD>1e-12){ const double ir=1.0/RnD; zx=Rx*ir; zy=Ry*ir; zz=Rz*ir; }
  else { zx=0.0; zy=0.0; zz=1.0; }
  double ax,ay; if(fabs(zx)<0.9){ax=1.0;ay=0.0;} else {ax=0.0;ay=1.0;}
  const double dot=ax*zx+ay*zy;
  double xx=ax-dot*zx, xy=ay-dot*zy, xz=-dot*zz;
  const double xn=sqrt(xx*xx+xy*xy+xz*xz);
  xx/=xn; xy/=xn; xz/=xn;
  const double yx=zy*xz-zz*xy, yy=zz*xx-zx*xz, yz=zx*xy-zy*xx;
  const double U[9]={xx,yx,zx, xy,yy,zy, xz,yz,zz};
  TR* __restrict__ Rq = dRs + q*9;
  { const double* R3 = U;  // unrolled qrot chain (TR) into global

  const TR r1_00 = R3[4];
  const TR r1_01 = R3[5];
  const TR r1_02 = R3[3];
  const TR r1_10 = R3[7];
  const TR r1_11 = R3[8];
  const TR r1_12 = R3[6];
  const TR r1_20 = R3[1];
  const TR r1_21 = R3[2];
  const TR r1_22 = R3[0];
  Rq[0] = r1_00;
  Rq[1] = r1_01;
  Rq[2] = r1_02;
  Rq[3] = r1_10;
  Rq[4] = r1_11;
  Rq[5] = r1_12;
  Rq[6] = r1_20;
  Rq[7] = r1_21;
  Rq[8] = r1_22;
}
  TR Fb_[2]; gen_boys_dev<TR>(1, eta*Rn*Rn, Fb_);
  const TR m2 = TR(-2.0)*eta;
  const TR s0_0_0_0 = Fb_[0];
  const TR s1_0_0_0 = m2*Fb_[1];
  const TR s0_0_0_1 = Rn*s1_0_0_0;
  const TR h0_0 = TR(0.9999999999999997)*s0_0_0_0;
  const TR h1_0 = TR(1.0000000000000004)*s0_0_0_1;
  TR* __restrict__ Tq = dTc + q*2;
  Tq[0] = pref*(TR(0.9999999999999998)*h0_0);
  Tq[1] = pref*(TR(-0.9999999999999996)*h1_0);
}
template<typename TR>
__global__ void routec_block_0010(int nq, int kprim,
    const TR* __restrict__ dRs, const TR* __restrict__ dTc,
    const TR* __restrict__ ftB, const TR* __restrict__ ftK,
    const int2* __restrict__ qlist, TR* __restrict__ out){
  const int q = blockIdx.x;  if(q >= nq) return;
  const int tid = threadIdx.x;
  extern __shared__ unsigned char smem_raw[];
  TR* smem = (TR*)smem_raw;
  TR* sRs = smem;            // [9]
  TR* sTc = smem + 9;    // [2]
  TR* sGb = smem + 11;            // [1*1]
  TR* sGk = smem + 12;  // [4*3]
  TR O[3];
  #pragma unroll
  for(int jc=0;jc<3;++jc) O[jc] = TR(0.0);
  for(int pq=0; pq<kprim; ++pq){
    const long base = (long)q*kprim + pq;
    __syncthreads();
    for(int s=tid; s<9; s+=32) sRs[s] = dRs[base*9+s];
    for(int s=tid; s<2; s+=32) sTc[s] = dTc[base*2+s];
    const int ib = qlist[base].x, ik = qlist[base].y;
    const TR* __restrict__ FTb = ftB + (size_t)ib*1;
    const TR* __restrict__ FTk = ftK + (size_t)ik*12;
    __syncthreads();
    if(tid < 1){
      sGb[0+tid] = FTb[0+tid];
    }
    if(tid < 3){
      sGk[3+tid] = FTk[0+tid];
      { // k=1 lam=1
        const TR f0=FTk[3+tid];
        const TR f1=FTk[6+tid];
        const TR f2=FTk[9+tid];
        sGk[0+tid] = sRs[0]*f0 + sRs[3]*f1 + sRs[6]*f2;
        sGk[6+tid] = sRs[1]*f0 + sRs[4]*f1 + sRs[7]*f2;
        sGk[9+tid] = sRs[2]*f0 + sRs[5]*f1 + sRs[8]*f2;
      }
    }
    __syncthreads();
    if(tid < 1){
      { const TR w = sTc[0]*sGb[0+tid];
        #pragma unroll
        for(int jc=0;jc<3;++jc) O[jc] += w*sGk[3+jc]; }
      { const TR w = sTc[1]*sGb[0+tid];
        #pragma unroll
        for(int jc=0;jc<3;++jc) O[jc] += w*sGk[6+jc]; }
    }
  } // kprim loop
  if(tid < 1){
    TR* __restrict__ o = out + (size_t)q*3 + (size_t)tid*3;
    #pragma unroll
    for(int jc=0;jc<3;++jc) o[jc] = O[jc];
  }
}
