  TR* sTc = smem + 34;    // [4]
  TR* sGb = smem + 38;            // [10*5]
  TR* sGk = smem + 88;  // [1*1]
  TR O[1];
  #pragma unroll
  for(int jc=0;jc<1;++jc) O[jc] = TR(0.0);
  for(int pq=0; pq<kprim; ++pq){
    const long base = (long)q*kprim + pq;
    __syncthreads();
    for(int s=tid; s<34; s+=32) sRs[s] = dRs[base*34+s];
    for(int s=tid; s<4; s+=32) sTc[s] = dTc[base*4+s];
    const int ib = qlist[base].x, ik = qlist[base].y;
    const TR* __restrict__ FTb = ftB + (size_t)ib*50;
