      sGb[25+tid] = FTb[20+tid];
      { // k=2 lam=2
        const TR f0=FTb[25+tid];
        const TR f1=FTb[30+tid];
        const TR f2=FTb[35+tid];
        const TR f3=FTb[40+tid];
        const TR f4=FTb[45+tid];
        sGb[0+tid] = sRs[9]*f0 + sRs[14]*f1 + sRs[19]*f2 + sRs[24]*f3 + sRs[29]*f4;
        sGb[10+tid] = sRs[10]*f0 + sRs[15]*f1 + sRs[20]*f2 + sRs[25]*f3 + sRs[30]*f4;
        sGb[30+tid] = sRs[11]*f0 + sRs[16]*f1 + sRs[21]*f2 + sRs[26]*f3 + sRs[31]*f4;
        sGb[40+tid] = sRs[12]*f0 + sRs[17]*f1 + sRs[22]*f2 + sRs[27]*f3 + sRs[32]*f4;
        sGb[45+tid] = sRs[13]*f0 + sRs[18]*f1 + sRs[23]*f2 + sRs[28]*f3 + sRs[33]*f4;
      }
    }
    if(tid < 1){
      sGk[0+tid] = FTk[0+tid];
    }
    __syncthreads();
    if(tid < 5){
      { const TR w = sTc[0]*sGb[15+tid] + sTc[1]*sGb[20+tid] + sTc[2]*sGb[25+tid] + sTc[3]*sGb[30+tid];
        #pragma unroll
        for(int jc=0;jc<1;++jc) O[jc] += w*sGk[0+jc]; }
    }
  } // kprim loop
  if(tid < 5){
    TR* __restrict__ o = out + (size_t)q*5 + (size_t)tid*1;
    #pragma unroll
    for(int jc=0;jc<1;++jc) o[jc] = O[jc];
  }
