template<typename TR>
__global__ void routec_block_0030(int nq, int kprim,
    const TR* __restrict__ dRs, const TR* __restrict__ dTc,
    const TR* __restrict__ ftB, const TR* __restrict__ ftK,
    const int2* __restrict__ qlist, TR* __restrict__ out){
  const int q = blockIdx.x;  if(q >= nq) return;
  const int tid = threadIdx.x;
  extern __shared__ unsigned char smem_raw[];
  TR* smem = (TR*)smem_raw;
  TR* sRs = smem;            // [83]
  TR* sTc = smem + 83;    // [6]
  TR* sGb = smem + 89;            // [1*1]
  TR* sGk = smem + 90;  // [20*7]
  TR O[7];
  #pragma unroll
  for(int jc=0;jc<7;++jc) O[jc] = TR(0.0);
  for(int pq=0; pq<kprim; ++pq){
    const long base = (long)q*kprim + pq;
    __syncthreads();
    for(int s=tid; s<83; s+=32) sRs[s] = dRs[base*83+s];
    for(int s=tid; s<6; s+=32) sTc[s] = dTc[base*6+s];
    const int ib = qlist[base].x, ik = qlist[base].y;
    const TR* __restrict__ FTb = ftB + (size_t)ib*1;
    const TR* __restrict__ FTk = ftK + (size_t)ik*140;
    __syncthreads();
    if(tid < 1){
      sGb[0+tid] = FTb[0+tid];
    }
    if(tid < 7){
      sGk[49+tid] = FTk[0+tid];
      { // k=1 lam=1
        const TR f0=FTk[7+tid];
        const TR f1=FTk[14+tid];
        const TR f2=FTk[21+tid];
        sGk[21+tid] = sRs[0]*f0 + sRs[3]*f1 + sRs[6]*f2;
        sGk[56+tid] = sRs[1]*f0 + sRs[4]*f1 + sRs[7]*f2;
        sGk[91+tid] = sRs[2]*f0 + sRs[5]*f1 + sRs[8]*f2;
      }
      sGk[63+tid] = FTk[28+tid];
      { // k=2 lam=2
        const TR f0=FTk[35+tid];
        const TR f1=FTk[42+tid];
        const TR f2=FTk[49+tid];
        const TR f3=FTk[56+tid];
        const TR f4=FTk[63+tid];
        sGk[7+tid] = sRs[9]*f0 + sRs[14]*f1 + sRs[19]*f2 + sRs[24]*f3 + sRs[29]*f4;
        sGk[28+tid] = sRs[10]*f0 + sRs[15]*f1 + sRs[20]*f2 + sRs[25]*f3 + sRs[30]*f4;
        sGk[70+tid] = sRs[11]*f0 + sRs[16]*f1 + sRs[21]*f2 + sRs[26]*f3 + sRs[31]*f4;
        sGk[98+tid] = sRs[12]*f0 + sRs[17]*f1 + sRs[22]*f2 + sRs[27]*f3 + sRs[32]*f4;
        sGk[119+tid] = sRs[13]*f0 + sRs[18]*f1 + sRs[23]*f2 + sRs[28]*f3 + sRs[33]*f4;
      }
      { // k=3 lam=1
        const TR f0=FTk[70+tid];
        const TR f1=FTk[77+tid];
        const TR f2=FTk[84+tid];
        sGk[35+tid] = sRs[0]*f0 + sRs[3]*f1 + sRs[6]*f2;
        sGk[77+tid] = sRs[1]*f0 + sRs[4]*f1 + sRs[7]*f2;
        sGk[105+tid] = sRs[2]*f0 + sRs[5]*f1 + sRs[8]*f2;
      }
      { // k=3 lam=3
        const TR f0=FTk[91+tid];
        const TR f1=FTk[98+tid];
        const TR f2=FTk[105+tid];
        const TR f3=FTk[112+tid];
        const TR f4=FTk[119+tid];
        const TR f5=FTk[126+tid];
        const TR f6=FTk[133+tid];
        sGk[0+tid] = sRs[34]*f0 + sRs[41]*f1 + sRs[48]*f2 + sRs[55]*f3 + sRs[62]*f4 + sRs[69]*f5 + sRs[76]*f6;
        sGk[14+tid] = sRs[35]*f0 + sRs[42]*f1 + sRs[49]*f2 + sRs[56]*f3 + sRs[63]*f4 + sRs[70]*f5 + sRs[77]*f6;
        sGk[42+tid] = sRs[36]*f0 + sRs[43]*f1 + sRs[50]*f2 + sRs[57]*f3 + sRs[64]*f4 + sRs[71]*f5 + sRs[78]*f6;
        sGk[84+tid] = sRs[37]*f0 + sRs[44]*f1 + sRs[51]*f2 + sRs[58]*f3 + sRs[65]*f4 + sRs[72]*f5 + sRs[79]*f6;
        sGk[112+tid] = sRs[38]*f0 + sRs[45]*f1 + sRs[52]*f2 + sRs[59]*f3 + sRs[66]*f4 + sRs[73]*f5 + sRs[80]*f6;
        sGk[126+tid] = sRs[39]*f0 + sRs[46]*f1 + sRs[53]*f2 + sRs[60]*f3 + sRs[67]*f4 + sRs[74]*f5 + sRs[81]*f6;
        sGk[133+tid] = sRs[40]*f0 + sRs[47]*f1 + sRs[54]*f2 + sRs[61]*f3 + sRs[68]*f4 + sRs[75]*f5 + sRs[82]*f6;
      }
    }
    __syncthreads();
    if(tid < 1){
      { const TR w = sTc[0]*sGb[0+tid];
        #pragma unroll
        for(int jc=0;jc<7;++jc) O[jc] += w*sGk[49+jc]; }
      { const TR w = sTc[1]*sGb[0+tid];
        #pragma unroll
        for(int jc=0;jc<7;++jc) O[jc] += w*sGk[56+jc]; }
      { const TR w = sTc[2]*sGb[0+tid];
        #pragma unroll
        for(int jc=0;jc<7;++jc) O[jc] += w*sGk[63+jc]; }
      { const TR w = sTc[3]*sGb[0+tid];
        #pragma unroll
        for(int jc=0;jc<7;++jc) O[jc] += w*sGk[70+jc]; }
      { const TR w = sTc[4]*sGb[0+tid];
        #pragma unroll
        for(int jc=0;jc<7;++jc) O[jc] += w*sGk[77+jc]; }
      { const TR w = sTc[5]*sGb[0+tid];
        #pragma unroll
        for(int jc=0;jc<7;++jc) O[jc] += w*sGk[84+jc]; }
    }
  } // kprim loop
  if(tid < 1){
    TR* __restrict__ o = out + (size_t)q*7 + (size_t)tid*7;
    #pragma unroll
    for(int jc=0;jc<7;++jc) o[jc] = O[jc];
  }
}
