template<typename TR>
__global__ void routec_block_2100_c1(int nq, int kprim,
    const TR* __restrict__ dRs, const TR* __restrict__ dTc,
    const TR* __restrict__ ftB, const TR* __restrict__ ftK,
    const int2* __restrict__ qlist, TR* __restrict__ out){
  const int q = blockIdx.x;  if(q >= nq) return;
  const int tid = threadIdx.x;
  extern __shared__ unsigned char smem_raw[];
  TR* smem = (TR*)smem_raw;
  TR* sRs = smem;            // [83]
  TR* sTc = smem + 83;    // [2]
  TR* sGb = smem + 85;            // [20*15]
  TR* sGk = smem + 385;  // [1*1]
  TR O[1];
  #pragma unroll
  for(int jc=0;jc<1;++jc) O[jc] = TR(0.0);
  for(int pq=0; pq<kprim; ++pq){
    const long base = (long)q*kprim + pq;
    __syncthreads();
    for(int s=tid; s<83; s+=32) sRs[s] = dRs[base*83+s];
    for(int s=tid; s<2; s+=32) sTc[s] = dTc[base*2+s];
    const int ib = qlist[base].x, ik = qlist[base].y;
    const TR* __restrict__ FTb = ftB + (size_t)ib*300;
    const TR* __restrict__ FTk = ftK + (size_t)ik*1;
    __syncthreads();
    if(tid < 15){
      sGb[105+tid] = FTb[0+tid];
      { // k=1 lam=1
        const TR f0=FTb[15+tid];
        const TR f1=FTb[30+tid];
        const TR f2=FTb[45+tid];
        sGb[120+tid] = sRs[1]*f0 + sRs[4]*f1 + sRs[7]*f2;
      }
    }
    if(tid < 1){
      sGk[0+tid] = FTk[0+tid];
    }
    __syncthreads();
    if(tid < 15){
      { const TR w = sTc[0]*sGb[105+tid] + sTc[1]*sGb[120+tid];
        #pragma unroll
        for(int jc=0;jc<1;++jc) O[jc] += w*sGk[0+jc]; }
    }
  } // kprim loop
  if(tid < 15){
    TR* __restrict__ o = out + (size_t)q*15 + (size_t)tid*1;
    #pragma unroll
    for(int jc=0;jc<1;++jc) o[jc] = O[jc];
  }
}
