        sGk[30+tid] = sRs[11]*f0 + sRs[16]*f1 + sRs[21]*f2 + sRs[26]*f3 + sRs[31]*f4;
        sGk[40+tid] = sRs[12]*f0 + sRs[17]*f1 + sRs[22]*f2 + sRs[27]*f3 + sRs[32]*f4;
        sGk[45+tid] = sRs[13]*f0 + sRs[18]*f1 + sRs[23]*f2 + sRs[28]*f3 + sRs[33]*f4;
      }
    }
    __syncthreads();
    if(tid < 1){
      { const TR w = sTc[0]*sGb[0+tid];
        #pragma unroll
        for(int jc=0;jc<5;++jc) O[jc] += w*sGk[15+jc]; }
      { const TR w = sTc[1]*sGb[0+tid];
        #pragma unroll
        for(int jc=0;jc<5;++jc) O[jc] += w*sGk[20+jc]; }
      { const TR w = sTc[2]*sGb[0+tid];
        #pragma unroll
        for(int jc=0;jc<5;++jc) O[jc] += w*sGk[25+jc]; }
      { const TR w = sTc[3]*sGb[0+tid];
        #pragma unroll
        for(int jc=0;jc<5;++jc) O[jc] += w*sGk[30+jc]; }
    }
  } // kprim loop
  if(tid < 1){
